/**
 * gcaptcha.js -- tek dosya: sunucu (challenge/verify/rate-limit/middleware)
 * VE widget'in kendisi (Cloudflare Turnstile tarzi checkbox/spinner/checkmark) burada.
 *
 * Hizli deneme:
 *   npm install express
 *   node gcaptcha.js
 *   -> http://localhost:3000  (widget + "Kayit Ol" testi tek sayfada)
 *
 * Gettic'in gercek backend'ine (app.js) baglamak icin:
 *   const { attachGcaptchaRoutes, requireGcaptcha } = require('./gcaptcha.js');
 *   attachGcaptchaRoutes(app);                        // /api/gcaptcha/challenge + /verify ekler
 *   app.post('/api/register', requireGcaptcha, ...);  // korumak istedigin her route'a ekle
 *   Widget'i kendi frontend'ine almak icin: sunucuyu bir kere calistirip
 *   http://localhost:3000/gcaptcha-widget.js ciktisini kaydet.
 *
 * Guvenlik ozeti (onceki mesajdakiyle ayni, sadece dosya sayisi azaldi):
 *   - Token istemcide degil, sunucunun SECRET'iyla imzalaniyor -> sahtesi uretilemez.
 *   - Token uretmeden once tarayici gercek bir proof-of-work cozuyor -> CPU maliyeti.
 *   - Token tek kullanimlik ve sureli; IP basina rate limit var.
 */
const crypto = require('crypto');
const express = require('express');

// ---------- Ayarlar ----------
const SECRET = process.env.GCAPTCHA_SECRET || crypto.randomBytes(32).toString('hex');
const DIFFICULTY = Number(process.env.GCAPTCHA_DIFFICULTY || 4); // yuksek = daha yavas/daha zor
const CHALLENGE_TTL_MS = 60_000;
const TOKEN_TTL_MS = 5 * 60_000;
const MAX_REQ_PER_IP_PER_MIN = 20;

// ---------- Bellek ici durum (tek instance icin yeterli; yatay olceklerken Redis'e tasi) ----------
const challenges = new Map();
const usedTokens = new Map();
const hits = new Map();

setInterval(() => {
  const now = Date.now();
  for (const [id, c] of challenges) if (c.expires < now) challenges.delete(id);
  for (const [id, exp] of usedTokens) if (exp < now) usedTokens.delete(id);
}, 30_000).unref();

function tooManyRequests(ip) {
  const now = Date.now();
  const recent = (hits.get(ip) || []).filter((t) => t > now - 60_000);
  recent.push(now);
  hits.set(ip, recent);
  return recent.length > MAX_REQ_PER_IP_PER_MIN;
}

function sign(payload) {
  const body = Buffer.from(JSON.stringify(payload)).toString('base64url');
  const sig = crypto.createHmac('sha256', SECRET).update(body).digest('base64url');
  return body + '.' + sig;
}

function verifyToken(token) {
  if (typeof token !== 'string' || !token.includes('.')) return null;
  const [body, sig] = token.split('.');
  const expected = crypto.createHmac('sha256', SECRET).update(body).digest('base64url');
  const a = Buffer.from(sig || '');
  const b = Buffer.from(expected);
  if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) return null;
  try {
    const payload = JSON.parse(Buffer.from(body, 'base64url').toString());
    if (!payload.exp || payload.exp < Date.now()) return null;
    return payload;
  } catch {
    return null;
  }
}

// ---------- Widget (Cloudflare Turnstile tarzi animasyon) ----------
// Bu, gcaptcha-widget.js ile birebir ayni kaynak; sadece bu dosyadan servis
// edilebilsin diye bir sabit icine aliniyor.
const WIDGET_JS = `/**
 * <gcaptcha-widget endpoint="/api/gcaptcha"></gcaptcha-widget>
 *
 * Gercek dogrulama akisi:
 *  1) Sunucudan bir "challenge" (seed + zorluk) istenir.
 *  2) Tarayici, gercek CPU maliyeti olan bir proof-of-work bulmaya calisir
 *     (SHA-256(seed + nonce) belirlenen sayida "0" ile baslayana kadar).
 *  3) Cozum sunucuya gonderilir; sunucu doğrularsa, sadece sunucunun bildigi
 *     gizli anahtarla imzalanmis, tek kullanimlik, sureli bir token doner.
 *  4) getValue() artik bu GERCEK imzali token'i dondurur - istemci bunu
 *     uydurmus olamaz, cunku imza sunucu gizli anahtariyla uretiliyor.
 *
 * Onemli: bu widget TEK BASINA yeterli degil. Token'i, korumak istedigin
 * her endpoint'te (kayit, giris, mesaj gonderme...) sunucu tarafinda
 * requireGcaptcha middleware'i ile MUTLAKA dogrulamalisin (bkz. gcaptcha-server.js).
 */
class GCaptchaWidget extends HTMLElement {
  static VERIFY_UI_MIN_MS = 500; // spinner'in en az bu kadar gorunmesi icin (cok hizli coz(ul)urse bile)

  constructor() {
    super();
    this.attachShadow({ mode: 'open' });
    this._verified = false;
    this._ready = false;
    this._token = null;
    this._expiryTimer = null;
  }

  get endpoint() {
    return this.getAttribute('endpoint') || '/api/gcaptcha';
  }

  connectedCallback() {
    const self = this;

    this.shadowRoot.innerHTML = \`
      <style>
        :host {
          display: block; margin: 8px 0; user-select: none; max-width: 300px;
          opacity: 0; transform: translateY(4px);
          animation: gcaptcha-enter 0.35s ease forwards;
        }
        @keyframes gcaptcha-enter { to { opacity: 1; transform: translateY(0); } }

        .gcaptcha-container {
          background: #fff; border: 1px solid #d3d7db; border-radius: 4px; padding: 2px;
          display: flex; align-items: center; justify-content: space-between; height: 65px;
          box-shadow: 0 1px 2px rgba(0,0,0,0.04);
          transition: border-color .4s ease, background .4s ease, box-shadow .6s ease;
        }
        .gcaptcha-container.verified { border-color: #b9c2cc; background: #fbfcfd; }
        .gcaptcha-container.flash { box-shadow: 0 0 0 3px rgba(90,170,120,0.25); }
        .gcaptcha-container.error { border-color: #d98b8b; }

        .gcaptcha-left {
          display: flex; align-items: center; gap: 14px; padding: 0 16px; height: 100%;
          cursor: pointer; border-radius: 4px 0 0 4px; outline: none;
        }
        .gcaptcha-left:hover:not(.disabled) { background: rgba(107,118,132,0.05); }
        .gcaptcha-left:focus-visible { box-shadow: inset 0 0 0 2px #7c9cf0; }
        .gcaptcha-left.disabled { cursor: default; }

        .gcaptcha-box {
          width: 26px; height: 26px; flex-shrink: 0; position: relative;
          border: 2.5px solid #c1c7cf; border-radius: 4px; background: #fff; box-sizing: border-box;
          transition: border-radius .35s ease, border-color .35s ease;
        }
        .gcaptcha-box[data-state="loading"],
        .gcaptcha-box[data-state="verifying"] { border-radius: 50%; border-color: transparent; }
        .gcaptcha-box[data-state="done"] { border-color: #b9c2cc; }

        .gcaptcha-ring {
          position: absolute; inset: 0; opacity: 0; transition: opacity .2s ease;
          animation: gcaptcha-rotate .85s linear infinite;
        }
        .gcaptcha-box[data-state="loading"] .gcaptcha-ring,
        .gcaptcha-box[data-state="verifying"] .gcaptcha-ring { opacity: 1; }
        @keyframes gcaptcha-rotate { to { transform: rotate(360deg); } }

        .gcaptcha-check {
          position: absolute; inset: 0; opacity: 0; transform: scale(0);
          transition: transform .4s cubic-bezier(.34,1.56,.64,1), opacity .2s ease;
        }
        .gcaptcha-box[data-state="done"] .gcaptcha-check { opacity: 1; transform: scale(1); }

        .gcaptcha-label {
          font-size: 13px; color: #35404a;
          font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
          transition: color .3s ease;
        }

        .gcaptcha-right { display: flex; flex-direction: column; align-items: flex-end; gap: 3px; padding: 0 14px; flex-shrink: 0; }
        .gcaptcha-logo { display: flex; align-items: center; gap: 5px; }
        .gcaptcha-logo img { width: 20px; height: 20px; border-radius: 3px; }
        .gcaptcha-logo span { font-size: 10px; font-weight: 700; color: #8b95a1; letter-spacing: .2px; }
        .gcaptcha-terms { font-size: 8px; color: #b7bfc7; }

        @media (prefers-reduced-motion: reduce) {
          :host { animation: none; opacity: 1; transform: none; }
          .gcaptcha-ring { animation: none; }
          .gcaptcha-check { transition: opacity .2s ease; transform: scale(1) !important; }
        }
      </style>

      <div class="gcaptcha-container" id="container">
        <div class="gcaptcha-left disabled" id="clickzone" role="checkbox" aria-checked="false"
             aria-disabled="true" aria-label="Ben robot değilim" tabindex="-1">
          <div class="gcaptcha-box" id="box" data-state="loading">
            <svg class="gcaptcha-ring" viewBox="0 0 26 26">
              <circle cx="13" cy="13" r="10" fill="none" stroke="#6b7684" stroke-width="2.5"
                      stroke-linecap="round" stroke-dasharray="16 47"/>
            </svg>
            <svg class="gcaptcha-check" viewBox="0 0 24 24" fill="none" stroke="#4a5561"
                 stroke-width="3" stroke-linecap="round" stroke-linejoin="round">
              <polyline points="20 6 9 17 4 12"/>
            </svg>
          </div>
          <span class="gcaptcha-label" id="label">Yükleniyor...</span>
        </div>
        <div class="gcaptcha-right">
          <div class="gcaptcha-logo">
            <img src="https://raw.githubusercontent.com/darking053official/gettic/main/1777062266055.png" alt="Gettic">
            <span>GETTIC</span>
          </div>
          <span class="gcaptcha-terms">Gizlilik · Şartlar</span>
        </div>
      </div>
    \`;

    const container = self.shadowRoot.getElementById('container');
    const clickzone = self.shadowRoot.getElementById('clickzone');
    const box = self.shadowRoot.getElementById('box');
    const label = self.shadowRoot.getElementById('label');

    const setReady = () => {
      box.dataset.state = 'idle';
      clickzone.classList.remove('disabled');
      clickzone.removeAttribute('aria-disabled');
      clickzone.tabIndex = 0;
      label.textContent = 'Ben robot değilim';
      self._ready = true;
    };

    const showError = (msg) => {
      box.dataset.state = 'idle';
      container.classList.add('error');
      label.textContent = msg;
      label.style.color = '#b45858';
      setTimeout(() => {
        container.classList.remove('error');
        label.textContent = 'Ben robot değilim';
        label.style.color = '#35404a';
      }, 2200);
    };

    // SHA-256(seed + nonce) belirlenen sayida "0" hex karakteriyle baslayana kadar dener.
    // Gercek CPU maliyeti burada - script yazan basit botlarin maliyetini yukseltir.
    async function solveProofOfWork(seed, difficulty) {
      const prefix = '0'.repeat(difficulty);
      const enc = new TextEncoder();
      let nonce = 0;
      while (true) {
        const digest = await crypto.subtle.digest('SHA-256', enc.encode(seed + nonce));
        const hex = [...new Uint8Array(digest)].map(b => b.toString(16).padStart(2, '0')).join('');
        if (hex.startsWith(prefix)) return nonce;
        nonce++;
        if (nonce % 2000 === 0) await new Promise((r) => requestAnimationFrame(r)); // arayuzu tikatma
      }
    }

    const runVerification = async () => {
      if (!self._ready || self._verified || box.dataset.state === 'verifying') return;

      box.dataset.state = 'verifying';
      clickzone.setAttribute('aria-disabled', 'true');
      label.textContent = 'Doğrulanıyor...';
      label.style.color = '#6b7684';
      const startedAt = Date.now();

      try {
        const challengeRes = await fetch(\`\${self.endpoint}/challenge\`, { method: 'POST' });
        if (!challengeRes.ok) throw new Error('challenge_failed');
        const { challengeId, seed, difficulty } = await challengeRes.json();

        const nonce = await solveProofOfWork(seed, difficulty);

        const verifyRes = await fetch(\`\${self.endpoint}/verify\`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ challengeId, nonce })
        });
        if (!verifyRes.ok) throw new Error('verify_failed');
        const { token, expiresInMs } = await verifyRes.json();

        // spinner'in goze carpmasi icin en az VERIFY_UI_MIN_MS bekle
        const elapsed = Date.now() - startedAt;
        if (elapsed < GCaptchaWidget.VERIFY_UI_MIN_MS) {
          await new Promise((r) => setTimeout(r, GCaptchaWidget.VERIFY_UI_MIN_MS - elapsed));
        }

        box.dataset.state = 'done';
        container.classList.add('verified', 'flash');
        setTimeout(() => container.classList.remove('flash'), 700);
        clickzone.setAttribute('aria-checked', 'true');
        clickzone.removeAttribute('aria-disabled');
        label.textContent = 'Doğrulandı!';
        label.style.color = '#35404a';

        self._verified = true;
        self._token = token;
        self.dispatchEvent(new CustomEvent('verify', { detail: { token }, bubbles: true, composed: true }));

        const ttl = typeof expiresInMs === 'number' ? expiresInMs : 300000;
        self._expiryTimer = setTimeout(() => self._expire(), ttl);
      } catch (err) {
        clickzone.removeAttribute('aria-disabled');
        showError('Doğrulama başarısız, tekrar dene');
        self.dispatchEvent(new CustomEvent('gcaptcha-error', { detail: { error: String(err) }, bubbles: true, composed: true }));
      }
    };

    clickzone.addEventListener('click', runVerification);
    clickzone.addEventListener('keydown', (e) => {
      if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); runVerification(); }
    });

    setTimeout(setReady, 700); // Turnstile'daki kisa "Loading" evresini yansitir
  }

  _expire() {
    if (!this._verified) return;
    this._verified = false;
    this._token = null;
    const box = this.shadowRoot.getElementById('box');
    const container = this.shadowRoot.getElementById('container');
    const clickzone = this.shadowRoot.getElementById('clickzone');
    const label = this.shadowRoot.getElementById('label');
    box.dataset.state = 'idle';
    container.classList.remove('verified');
    clickzone.setAttribute('aria-checked', 'false');
    label.textContent = 'Süresi doldu, tekrar doğrula';
    label.style.color = '#b45858';
    setTimeout(() => { label.textContent = 'Ben robot değilim'; label.style.color = '#35404a'; }, 2000);
    this.dispatchEvent(new CustomEvent('expire', { bubbles: true, composed: true }));
  }

  getValue() {
    return this._verified ? this._token : null;
  }

  reset() {
    clearTimeout(this._expiryTimer);
    this._verified = false;
    this._ready = false;
    this._token = null;
    this.connectedCallback();
  }
}

customElements.define('gcaptcha-widget', GCaptchaWidget);
`;

// ---------- Demo sayfasi ----------
const DEMO_HTML = `<!DOCTYPE html>
<html lang="tr">
<head>
<meta charset="UTF-8">
<title>Gettic Guvenlik - Onizleme</title>
<style>
  body {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    background: #eef0f2; display: flex; flex-direction: column; align-items: center;
    justify-content: center; height: 100vh; margin: 0; gap: 14px;
  }
  h1 { font-size: 15px; color: #4a5561; font-weight: 600; margin: 0; }
  p { font-size: 12px; color: #8b95a1; margin: 0; }
  button {
    margin-top: 4px; padding: 8px 16px; font-size: 13px; border-radius: 4px;
    border: 1px solid #c1c7cf; background: #fff; cursor: pointer;
  }
  button:disabled { opacity: 0.45; cursor: default; }
  pre { font-size: 11px; background: #fff; border: 1px solid #d3d7db; border-radius: 4px; padding: 10px 14px; min-width: 220px; min-height: 16px; }
</style>
</head>
<body>
  <h1>Gettic Guvenlik Dogrulamasi</h1>
  <p>Kutuya tikla -- gercek bir proof-of-work cozulup sunucudan imzali token alinacak</p>
  <gcaptcha-widget id="widget"></gcaptcha-widget>
  <button id="submitBtn" disabled>Kayit Ol (test)</button>
  <pre id="result"></pre>

  <script>
${WIDGET_JS}
  </script>
  <script>
    const widget = document.getElementById('widget');
    const submitBtn = document.getElementById('submitBtn');
    const result = document.getElementById('result');
    let token = null;

    widget.addEventListener('verify', (e) => {
      token = e.detail.token;
      submitBtn.disabled = false;
    });
    widget.addEventListener('expire', () => {
      token = null;
      submitBtn.disabled = true;
    });

    submitBtn.addEventListener('click', async () => {
      submitBtn.disabled = true;
      const res = await fetch('/api/register', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ gcaptchaToken: token })
      });
      result.textContent = JSON.stringify(await res.json(), null, 2);
    });
  </script>
</body>
</html>`;

// ---------- Gettic'in gercek backend'ine eklenecek kisim ----------
function attachGcaptchaRoutes(app, basePath) {
  basePath = basePath || '/api/gcaptcha';

  app.post(basePath + '/challenge', (req, res) => {
    if (tooManyRequests(req.ip)) return res.status(429).json({ error: 'too_many_requests' });
    const challengeId = crypto.randomBytes(16).toString('hex');
    const seed = crypto.randomBytes(16).toString('hex');
    challenges.set(challengeId, { seed, expires: Date.now() + CHALLENGE_TTL_MS });
    res.json({ challengeId, seed, difficulty: DIFFICULTY });
  });

  app.post(basePath + '/verify', express.json(), (req, res) => {
    if (tooManyRequests(req.ip)) return res.status(429).json({ error: 'too_many_requests' });
    const { challengeId, nonce } = req.body || {};
    const challenge = challenges.get(challengeId);
    if (!challenge || challenge.expires < Date.now()) {
      return res.status(400).json({ error: 'challenge_invalid_or_expired' });
    }
    const hash = crypto.createHash('sha256').update(challenge.seed + String(nonce)).digest('hex');
    if (!hash.startsWith('0'.repeat(DIFFICULTY))) {
      return res.status(400).json({ error: 'proof_invalid' });
    }
    challenges.delete(challengeId);
    const exp = Date.now() + TOKEN_TTL_MS;
    const token = sign({ id: crypto.randomBytes(8).toString('hex'), ip: req.ip, exp });
    res.json({ token, expiresInMs: TOKEN_TTL_MS });
  });
}

function requireGcaptcha(req, res, next) {
  const token = (req.body && req.body.gcaptchaToken) || req.headers['x-gcaptcha-token'];
  const payload = verifyToken(token);
  if (!payload) return res.status(403).json({ error: 'gcaptcha_required' });
  if (usedTokens.has(payload.id)) return res.status(403).json({ error: 'gcaptcha_already_used' });
  usedTokens.set(payload.id, payload.exp);
  next();
}

// ---------- `node gcaptcha.js` ile dogrudan calistirilinca kendi demo sunucusunu ayaga kaldirir ----------
if (require.main === module) {
  const app = express();
  app.set('trust proxy', 1); // Render/Cloudflare gibi bir proxy arkasindaysan sart

  attachGcaptchaRoutes(app);

  app.get('/', (req, res) => res.type('html').send(DEMO_HTML));
  app.get('/gcaptcha-widget.js', (req, res) => res.type('application/javascript').send(WIDGET_JS));
  app.post('/api/register', express.json(), requireGcaptcha, (req, res) => {
    res.json({ ok: true, message: 'Kayit basarili (ornek uc nokta)' });
  });

  const PORT = process.env.PORT || 3000;
  app.listen(PORT, () => console.log('http://localhost:' + PORT));
}

module.exports = { attachGcaptchaRoutes, requireGcaptcha };
